using System;using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckWifeCarrying.Editor {public static class WifeFixtures {public static void Run(){int checks=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Wife fixture: "+label);checks++;};var s=new SportsRaceSeries();s.Reset(4,false);s.BeginRound();s.Resolve(new[]{10f,11f,12f,13f});check(s.total[0]==4&&s.total[1]==3&&s.total[2]==2&&s.total[3]==1,"four-pair placement points");check(!s.Resolve(new[]{1f,2f,3f,4f})&&s.completed==1,"one race lock");s.Reset(4,false);for(int i=0;i<3;i++){s.BeginRound();s.Resolve(new[]{10f,10f,float.PositiveInfinity,float.PositiveInfinity});}check(s.total[0]==12&&s.total[2]==0&&s.winner<0&&s.eligible==3,"DNF zero and true tied leaders only");s.BeginRound();s.Resolve(new[]{12f,11f,float.PositiveInfinity,float.PositiveInfinity});check(s.winner==1&&s.completed==4,"extra race resolves tied series");check(SportsRaceSeries.Count(s.eligible)==2,"extra competitors mask excludes other pairs");Debug.Log("WIFE_RULE_FIXTURES_PASS count="+checks);}}}
